for (auto const &edge : edges) {
    RT::Cell_handle c = edge.first;
    unsigned i = edge.second;
    for (unsigned j = 0; j < 4; ++j) {
        if (j == i) {
            continue;
        }
        if (is_large_facet(rt, std::make_pair(c, j), threshold)) {
            std::vector<unsigned> vertices;
            vertices.push_back(c->vertex(i)->id());
            vertices.push_back(c->vertex(j)->id());
            filament_mesh.push_back(vertices, 0.0);
        }
    }
}
return filament_mesh;

